// The web host's build (docs/mcp-apps.md C9, piece 11): src/views/web.ts alone, no React, into
// ../../kit/views/web.js + web.css, the files the hub's page `GET /v/<agent>/<call>` loads
// (mcp-apps-sandbox's). Committed like kit's other built files (packaging copies kit/ whole);
// `pnpm build:views-web` writes them; `pnpm build` runs scripts/views-web.mts --check, red when
// they differ. Each file starts with a 'generated by' banner (tests/js_guard.py).
import { resolve } from 'node:path';
import { defineConfig, type Plugin } from 'vite';

const BANNER = '/* generated by apps/desktop/views.web.vite.config.ts from src/views/web.ts (pnpm -C apps/desktop build:views-web), never hand-edited */';

/** The banner on each file's first line, after the minifier (which drops rollup's own banner). */
function banner(): Plugin {
  return {
    name: 'bise-views-banner',
    enforce: 'post',
    generateBundle(_, bundle) {
      for (const f of Object.values(bundle)) {
        if (f.type === 'chunk') f.code = `${BANNER}\n${f.code}`;
        else if (f.fileName.endsWith('.css') && typeof f.source === 'string') f.source = `${BANNER}\n${f.source}`;
      }
    },
  };
}

export default defineConfig({
  plugins: [banner()],
  // no React here (the hooks live in src/views/hooks.ts): a library that still reads it is told production
  define: { 'process.env.NODE_ENV': JSON.stringify('production') },
  resolve: { alias: { '@': resolve(__dirname, 'src') } },
  build: {
    outDir: resolve(__dirname, '../../kit/views'),
    emptyOutDir: true,
    minify: true,
    sourcemap: false,
    cssCodeSplit: false,
    lib: { entry: resolve(__dirname, 'src/views/web.ts'), formats: ['iife'], name: 'biseView', fileName: () => 'web.js', cssFileName: 'web' },
  },
});
